/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-radio-group-gap.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: block;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: flex;
  flex-direction: column;
  gap: var(--an-space-2, 0.5rem);
  font-family: inherit;
}

.label {
  color: var(--an-color-fg-1, #18181b);
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1.4;
}

.group {
  display: flex;
  flex-wrap: wrap;
  gap: var(--an-radio-group-gap, var(--an-space-3, 0.75rem));
}

:host([disabled]) .base {
  opacity: 0.6;
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return Object.keys(this.defaults).map(toKebabCase);
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

/* Hooks: --an-radio-size | --an-radio-accent | --an-radio-border-color.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: inline-block;
  vertical-align: middle;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: inline-flex;
  align-items: center;
  gap: var(--an-space-2, 0.5rem);
  color: var(--an-color-fg-1, #18181b);
  font-family: inherit;
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1.4;
  cursor: pointer;
}

/* Visually hidden, but still focusable and operable by the platform. */
.input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: 0;
  padding: 0;
  border: 0;
  opacity: 0;
  pointer-events: none;
  appearance: none;
  -webkit-appearance: none;
}

.control {
  box-sizing: border-box;
  display: inline-grid;
  place-items: center;
  flex: none;
  inline-size: var(--an-radio-size, var(--an-space-4, 1rem));
  block-size: var(--an-radio-size, var(--an-space-4, 1rem));
  border: 1px solid var(--an-radio-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-radius-full, 9999px);
  background: var(--an-color-bg-1, #ffffff);
}

.control::after {
  content: '';
  inline-size: 50%;
  block-size: 50%;
  border-radius: inherit;
  background: var(--an-color-bg-1, #ffffff);
  transform: scale(0);
  transition: transform 120ms ease-out;
}

.input:checked + .control {
  border-color: var(--an-radio-accent, var(--an-color-accent-9, #2563eb));
  background: var(--an-radio-accent, var(--an-color-accent-9, #2563eb));
}

.input:checked + .control::after {
  transform: scale(1);
}

.input:focus-visible + .control {
  outline: 2px solid var(--an-color-accent-9, #2563eb);
  outline-offset: 2px;
}

.input:disabled + .control {
  opacity: 0.5;
}

:host([disabled]) .base {
  cursor: not-allowed;
  opacity: 0.6;
}

@media (prefers-reduced-motion: reduce) {
  .control::after {
    transition: none;
  }
}

import radioStyles from './an-radio.css?inline';
import { AnElement } from '../internal/base';

/** Payload of `an-radio-select`, dispatched when the control becomes checked. */
export interface AnRadioEventDetail {
  /** The `value` of the radio that got selected. */
  value: string;
  /** The click / change event that triggered the selection. */
  originalEvent: Event;
}

/** `&` -> `&amp;`, so attribute text can never break out of the markup. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/**
 * `<an-radio>` — one option of a radio group.
 *
 * The element itself is **not** form associated: a standalone radio has no
 * meaningful submitted value, so `<an-radio-group>` owns the form entry. The
 * host only renders a real `<input type="radio">` (focus, keyboard activation
 * and the accessible role come from the platform) and reports a selection with
 * `an-radio-select`, which the group listens to.
 *
 * The native inputs live in separate shadow roots, one per `<an-radio>`, so the
 * browser does not group them even when their `name` matches. Arrow-key
 * navigation is therefore implemented by the group; see `an-radio-group.ts`.
 *
 * @attr {string} value - Submitted value of the option.
 * @attr {boolean} checked - Checked state, driven by the owning `<an-radio-group>`.
 * @attr {boolean} disabled - Disables the option and blocks selection.
 * @slot - Label text of the option.
 * @fires an-radio-connect - Fired when the option connects, so a group can re-sync after a late upgrade.
 * @fires an-radio-select - Fired when this option becomes checked; `detail = { value, originalEvent }`.
 * @cssprop --an-radio-size - Edge length of the painted control; defaults to `--an-space-4` (1rem).
 * @cssprop --an-radio-accent - Checked fill and border colour; defaults to `--an-color-accent-9`.
 * @cssprop --an-radio-border-color - Unchecked border colour; defaults to `--an-color-border-1`.
 * @csspart base - The `<label>` wrapper around the control and the label text.
 * @csspart control - The painted radio control (a decorative sibling of the native input).
 * @csspart label - The slot wrapper for the visible label text.
 */
export class AnRadio extends AnElement {
  static override styles = radioStyles;

  static override defaults = {
    value: '',
    checked: false,
    disabled: false,
  };

  /** Submitted value of the option. */
  declare value: string;
  /** Checked state, driven by the owning `<an-radio-group>`. */
  declare checked: boolean;
  /** Disabled state, either its own or pushed down by the group. */
  declare disabled: boolean;

  /**
   * Roving tab stop inside a radio group. `<an-radio-group>` keeps exactly one
   * enabled radio `tabbable`, so Tab enters the group once and the arrows move
   * inside it. A standalone radio stays tabbable.
   */
  #tabbable = true;

  /** Whether focus currently sits on the inner input. */
  #focusWithin = false;

  constructor() {
    super();
    // Delegation: clicks on the control, on the label text *and* on slotted
    // content all bubble to the host.
    this.addEventListener('click', this.#onClick);
    const root = this.shadowRoot!;
    root.addEventListener('change', this.#onChange);
    root.addEventListener('focusin', this.#onFocusIn);
    root.addEventListener('focusout', this.#onFocusOut);
  }

  get tabbable(): boolean {
    return this.#tabbable;
  }

  set tabbable(next: boolean) {
    const tabbable = Boolean(next);
    if (tabbable === this.#tabbable) return;
    this.#tabbable = tabbable;
    this.requestUpdate();
  }

  /**
   * Re-rendering replaces the inner `<input>`; without this the platform would
   * drop focus to `<body>` every time the checked state changes.
   */
  override requestUpdate(): void {
    const focused = this.#focusWithin;
    super.requestUpdate();
    if (focused && this.isConnected) this.#input?.focus();
  }

  /** Focus lands on the native radio, not on the (unfocusable) host. */
  override focus(options?: FocusOptions): void {
    this.#input?.focus(options);
  }

  protected render(): string {
    const attrs =
      ` class="input" type="radio"` +
      ` value="${escapeHtml(this.value)}"` +
      (this.checked ? ' checked aria-checked="true"' : ' aria-checked="false"') +
      (this.disabled ? ' disabled aria-disabled="true"' : '') +
      ` tabindex="${this.#tabbable ? 0 : -1}"`;
    return (
      `<label class="base" part="base">` +
      `<input${attrs} />` +
      `<span class="control" part="control" aria-hidden="true"></span>` +
      `<span class="label" part="label"><slot></slot></span>` +
      `</label>`
    );
  }

  protected override onConnect(): void {
    // Lets an owning group finish its registration sync even when the option is
    // upgraded after the group (the group may not see a `slotchange` for it).
    this.emit('an-radio-connect', { value: this.value });
  }

  /** Becomes checked and tells the group; already-checked radios stay silent. */
  #select(originalEvent: Event): void {
    if (this.disabled || this.checked) return;
    this.checked = true;
    this.emit<AnRadioEventDetail>('an-radio-select', {
      value: this.value,
      originalEvent,
    });
  }

  #onClick = (event: MouseEvent): void => {
    this.#select(event);
  };

  /**
   * Keyboard activation (Space) through the native input. Mouse clicks are
   * handled by `#onClick`; the subsequent `change` then finds the radio already
   * checked and stays silent.
   */
  #onChange = (event: Event): void => {
    if (event.target !== this.#input) return;
    this.#select(event);
  };

  #onFocusIn = (): void => {
    this.#focusWithin = true;
  };

  #onFocusOut = (): void => {
    this.#focusWithin = false;
  };

  get #input(): HTMLInputElement | null {
    return this.shadowRoot?.querySelector('input') ?? null;
  }
}

import groupStyles from './an-radio-group.css?inline';
import { AnElement } from '../internal/base';
import type { AnRadio, AnRadioEventDetail } from '../radio/an-radio';

/** Payload of `an-radio-change`. */
export interface AnRadioGroupEventDetail {
  /** The value of the radio that is now selected. */
  value: string;
  /** The click / keyboard event that triggered the selection. */
  originalEvent: Event;
}

/** Shown to the owning form when `required` is set and nothing is selected. */
const REQUIRED_MESSAGE = '请选择一个选项';

/** `&` -> `&amp;`, so attribute text can never break out of the markup. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/** True once the option has been upgraded into `AnRadio` (property accessors exist). */
function isUpgraded(radio: AnRadio): boolean {
  return typeof (radio as unknown as { tabbable?: unknown }).tabbable === 'boolean';
}

/**
 * `<an-radio-group>` — the form-associated half of the radio pair.
 *
 * The group owns the value, the form entry and validation; each child
 * `<an-radio>` is a dumb option that only renders a native `<input type="radio">`.
 * Child options register through `slotchange`, report a click / keyboard
 * activation with `an-radio-select`, and receive their `checked` / `disabled` /
 * roving-tab state back from the group.
 *
 * Native radios are grouped by tree root, and every `<an-radio>` keeps its input
 * in a separate shadow root, so the platform does **not** group them. Arrow-key
 * navigation is therefore implemented here: `keydown` is delegated from the
 * shadow root and the group moves (and selects) the next enabled option itself.
 *
 * @attr {string} name - Field name used when the value is submitted with the owning form.
 * @attr {string} value - Selected value, seeded by the attribute but never written back by the property.
 * @attr {string} label - Visible label, also used to name the `radiogroup` for assistive technology.
 * @attr {boolean} disabled - Disables every option and clears the form entry and validity.
 * @attr {boolean} required - Participates in constraint validation (`valueMissing` when nothing is selected).
 * @fires an-radio-change - Fired when the selection changes; `detail = { value, originalEvent }`.
 * @cssprop --an-radio-group-gap - Gap between options; defaults to `--an-space-3` (0.75rem).
 * @csspart base - Outer wrapper around the label and the options.
 * @csspart label - The visible group label; rendered only when `label` is non-empty.
 * @csspart group - The `role="radiogroup"` container holding the options.
 */
export class AnRadioGroup extends AnElement {
  static override formAssociated = true;

  static override styles = groupStyles;

  static override defaults = {
    name: '',
    label: '',
    disabled: false,
    required: false,
  };

  /** Form field name. */
  declare name: string;
  /** Visible label of the group; also names the `radiogroup` for assistive tech. */
  declare label: string;
  /** Disables the whole group, including every child radio. */
  declare disabled: boolean;
  /** Requires a selection for form submission. */
  declare required: boolean;

  /**
   * Selected value. Deliberately **not** attribute-backed: the selection is
   * runtime state, so assigning `.value` must not rewrite the `value` attribute.
   */
  #value = '';

  /** Selection at mount, restored by `form.reset()`. */
  #initialValue = '';

  /**
   * Latches the reset target the first time options exist. The parser connects
   * the host before its children are parsed, so this can not happen in
   * `connectedCallback`.
   */
  #captured = false;

  /** Set by `formDisabledCallback` (e.g. a disabled ancestor `<fieldset>`). */
  #formDisabled = false;

  /** A child's own disabled state, kept apart from the group-imposed one. */
  #intrinsicDisabled = new WeakMap<AnRadio, boolean>();

  /** The value this group last wrote to `radio.disabled`. */
  #appliedDisabled = new WeakMap<AnRadio, boolean>();

  /** Deferred initial-state capture is already queued. */
  #captureScheduled = false;

  /** `value` and the forwarded ARIA names are observed outside `defaults`. */
  static override get observedAttributes(): string[] {
    return [...super.observedAttributes, 'value', 'aria-label', 'aria-labelledby'];
  }

  constructor() {
    super();
    const root = this.shadowRoot!;
    root.addEventListener('slotchange', this.#onSlotChange);
    // `keydown` and the radio's internal event are composed, so they reach the
    // host; delegation keeps working across the group's own re-renders.
    this.addEventListener('keydown', this.#onKeydown);
    this.addEventListener('an-radio-select', this.#onRadioSelect);
    // An option that upgrades after the group tells it to re-sync.
    this.addEventListener('an-radio-connect', this.#onRadioConnect);
  }

  get value(): string {
    return this.#value;
  }

  set value(next: string | null) {
    this.#setValue(next === null || next === undefined ? '' : String(next));
  }

  /** The attribute seeds the value; it is never written back by the property. */
  override attributeChangedCallback(
    name: string,
    oldValue: string | null,
    value: string | null,
  ): void {
    if (name === 'value') {
      if (oldValue !== value) this.#setValue(value ?? '');
      return;
    }
    if (name === 'aria-label' || name === 'aria-labelledby') {
      if (oldValue !== value) this.requestUpdate();
      return;
    }
    super.attributeChangedCallback(name, oldValue, value);
  }

  protected render(): string {
    const label = this.label;
    // A visible label names the group from inside the shadow root; otherwise the
    // consumer-provided ARIA name is forwarded.
    const name = label
      ? ' aria-labelledby="group-label"'
      : this.#forwardedName();
    return (
      `<div class="base" part="base">` +
      (label
        ? `<span class="label" part="label" id="group-label">${escapeHtml(label)}</span>`
        : '') +
      `<div class="group" part="group" role="radiogroup"` +
      ` aria-required="${this.required}"${name}><slot></slot></div>` +
      `</div>`
    );
  }

  protected override afterRender(): void {
    const internals = this.internals;
    if (internals) {
      internals.ariaDisabled = this.disabled || this.#formDisabled ? 'true' : null;
      internals.ariaRequired = this.required ? 'true' : null;
    }
    this.#syncChildren();
  }

  protected override onConnect(): void {
    // Children created by the parser may not exist yet while this runs; the
    // deferred capture below sees them even when no `slotchange` is emitted.
    this.#syncChildren();
  }

  protected override onFormReset(): void {
    this.#value = this.#initialValue;
    this.requestUpdate();
    this.#syncChildren();
  }

  /** Mirrors a platform-level disable (e.g. ancestor `<fieldset disabled>`). */
  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    this.requestUpdate();
  }

  #setValue(next: string): void {
    if (next === this.#value) return;
    this.#value = next;
    this.requestUpdate();
  }

  /**
   * The `<an-radio>` options directly owned by this group, in DOM order. Nested
   * groups keep their own options, so the search stops at the first level.
   */
  #radios(): AnRadio[] {
    return Array.from(this.children).filter(
      (child) => child.localName === 'an-radio',
    ) as unknown as AnRadio[];
  }

  /** Pushes the group state down onto every option. */
  #syncChildren(): void {
    const radios = this.#radios();
    // An explicit value needs no deferred adoption, so the reset target can be
    // latched synchronously — `form.reset()` may run before the microtask does.
    if (
      !this.#captured &&
      this.#value !== '' &&
      radios.length > 0 &&
      radios.every(isUpgraded)
    ) {
      this.#initialValue = this.#value;
      this.#captured = true;
    }
    const groupDisabled = this.disabled || this.#formDisabled;
    for (const radio of radios) {
      // Before the initial state is captured, an empty value leaves the options
      // alone: a `checked` option in markup is the seed for the group value.
      if (this.#value !== '') {
        const selected = radio.value === this.#value;
        if (radio.checked !== selected) radio.checked = selected;
      } else if (this.#captured && radio.checked) {
        radio.checked = false;
      }
      this.#applyDisabled(radio, groupDisabled);
    }

    const enabled = radios.filter((radio) => !radio.disabled);
    const roving =
      enabled.find((radio) =>
        this.#value !== '' ? radio.value === this.#value : radio.checked,
      ) ??
      enabled[0] ??
      null;
    for (const radio of radios) {
      const tabbable = radio === roving;
      if (radio.tabbable !== tabbable) radio.tabbable = tabbable;
    }

    this.#scheduleCapture();
    this.#syncForm();
  }

  /**
   * Latches the reset target once every option exists and is upgraded. The
   * parser connects the host before its children, so this runs in a microtask
   * (and again when a late option reports `an-radio-connect`).
   */
  #capture(): void {
    if (this.#captured) return;
    const radios = this.#radios();
    if (radios.length === 0 || !radios.every(isUpgraded)) return;
    if (this.#value === '') {
      const checked = radios.find((radio) => radio.checked);
      if (checked) this.#value = checked.value;
    }
    this.#initialValue = this.#value;
    this.#captured = true;
  }

  #scheduleCapture(): void {
    if (this.#captured || this.#captureScheduled) return;
    const radios = this.#radios();
    if (radios.length === 0 || !radios.every(isUpgraded)) return;
    this.#captureScheduled = true;
    queueMicrotask(() => {
      this.#captureScheduled = false;
      if (!this.isConnected) return;
      this.#capture();
      this.#syncChildren();
    });
  }

  /**
   * Group disable wins, but a child that was disabled on its own stays disabled
   * once the group is re-enabled.
   */
  #applyDisabled(radio: AnRadio, groupDisabled: boolean): void {
    const applied = this.#appliedDisabled.get(radio);
    const current = radio.disabled;
    if (applied !== undefined && current !== applied) {
      this.#intrinsicDisabled.set(radio, current);
    }
    const intrinsic = this.#intrinsicDisabled.get(radio) ?? current;
    const next = groupDisabled || intrinsic;
    if (current !== next) radio.disabled = next;
    this.#appliedDisabled.set(radio, next);
    this.#intrinsicDisabled.set(radio, intrinsic);
  }

  /** Keeps `FormData`, validity and the required message in step with the value. */
  #syncForm(): void {
    const internals = this.internals;
    if (!internals) return;
    if (this.disabled || this.#formDisabled) {
      internals.setFormValue(null);
      internals.setValidity({});
      return;
    }
    // A value that matches no option is not a selection: it stays out of
    // FormData and keeps a required group invalid, like a native radio group.
    const selected =
      this.#value !== '' && this.#radios().some((radio) => radio.value === this.#value);
    internals.setFormValue(selected ? this.#value : null);
    if (this.required && !selected) {
      const anchor = this.#firstInput();
      internals.setValidity(
        { valueMissing: true },
        REQUIRED_MESSAGE,
        anchor ?? undefined,
      );
    } else {
      internals.setValidity({});
    }
  }

  /** The first option's inner input, used as the focus target of the validity. */
  #firstInput(): HTMLInputElement | null {
    for (const radio of this.#radios()) {
      const input = radio.shadowRoot?.querySelector('input');
      if (input) return input;
    }
    return null;
  }

  /** Selects `radio` and announces the change, unless nothing actually changed. */
  #selectRadio(radio: AnRadio, originalEvent: Event): void {
    if (this.disabled || this.#formDisabled || radio.disabled) return;
    const value = radio.value;
    if (value === this.#value) return;
    this.#value = value;
    this.#syncChildren();
    this.emit<AnRadioGroupEventDetail>('an-radio-change', { value, originalEvent });
  }

  /** The `<an-radio>` child whose subtree emitted `event`, if any. */
  #radioFromEvent(event: Event): AnRadio | null {
    const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
    for (const node of path) {
      if (node instanceof HTMLElement && node.localName === 'an-radio' && node.parentElement === this) {
        return node as AnRadio;
      }
    }
    return null;
  }

  #onSlotChange = (): void => {
    this.#syncChildren();
  };

  #onRadioConnect = (event: Event): void => {
    if (!this.#radioFromEvent(event)) return;
    this.#syncChildren();
  };

  #onRadioSelect = (event: Event): void => {
    const radio = this.#radioFromEvent(event);
    if (!radio) return;
    const detail = (event as CustomEvent<AnRadioEventDetail | undefined>).detail;
    this.#selectRadio(radio, detail?.originalEvent ?? event);
  };

  /**
   * Arrow-key navigation, implemented here because the native inputs live in
   * separate shadow roots and the platform never groups them. Home / End follow
   * the same roving-focus pattern.
   */
  #onKeydown = (event: KeyboardEvent): void => {
    const radio = this.#radioFromEvent(event);
    if (!radio || radio.disabled) return;

    const enabled = this.#radios().filter((candidate) => !candidate.disabled);
    const index = enabled.indexOf(radio);
    if (index === -1) return;

    let next = -1;
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        next = (index + 1) % enabled.length;
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        next = (index - 1 + enabled.length) % enabled.length;
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = enabled.length - 1;
        break;
      default:
        return;
    }

    const target = enabled[next];
    if (!target) return;
    event.preventDefault();
    this.#selectRadio(target, event);
    target.focus();
  };

  /**
   * Platform parity for form-associated custom elements: the host carries no
   * `validationMessage` of its own, so the message the platform computed is read
   * off the internals here — this is what `<an-field>` displays.
   */
  get validationMessage(): string {
    return this.internals?.validationMessage ?? '';
  }

  /** Platform constraint state; `undefined` when the element has no internals. */
  get validity(): ValidityState | undefined {
    return this.internals?.validity;
  }

  /** `aria-label` / `aria-labelledby` only when no visible group label exists. */
  #forwardedName(): string {
    const label = this.getAttribute('aria-label');
    const labelledby = this.getAttribute('aria-labelledby');
    return (
      (label ? ` aria-label="${escapeHtml(label)}"` : '') +
      (labelledby ? ` aria-labelledby="${escapeHtml(labelledby)}"` : '')
    );
  }
}
